import { readFile, writeFile } from "node:fs/promises"
import { resolve } from "node:path"

import type { AnnotationDefinition } from "./registry"

type AnnotationExtension = {
  annotation: AnnotationDefinition<string, unknown, unknown, string>
}

const header =
  "/* This file is generated by @finspotter/annotations/generator. Do not edit. */"

function assertValidExtensions(extensions: readonly AnnotationExtension[]) {
  const names = new Set<string>()
  const packageNames = new Set<string>()

  for (const { annotation } of extensions) {
    if (names.has(annotation.name))
      throw new Error(`Duplicate annotation name '${annotation.name}'`)
    if (packageNames.has(annotation.packageName))
      throw new Error(
        `Duplicate annotation package '${annotation.packageName}'`
      )

    names.add(annotation.name)
    packageNames.add(annotation.packageName)
  }
}

function generateBaseConfig(extensions: readonly AnnotationExtension[]) {
  const imports = extensions.flatMap(({ annotation }, index) => [
    `import { annotation as annotation${index} } from ${JSON.stringify(annotation.packageName)}`,
    `import type { machine as machine${index} } from ${JSON.stringify(`${annotation.packageName}/machine`)}`,
  ])
  const machines = extensions.map(
    ({ annotation }, index) =>
      `  ${JSON.stringify(annotation.name)}: typeof machine${index}`
  )

  return [
    header,
    "",
    ...imports,
    "",
    `export const annotations = [${extensions.map((_, index) => `annotation${index}`).join(", ")}] as const`,
    "",
    "export type AnnotationMachines = {",
    ...machines,
    "}",
    "",
  ].join("\n")
}

function generateReactConfig(extensions: readonly AnnotationExtension[]) {
  const imports = extensions.map(
    ({ annotation }, index) =>
      `import * as annotation${index} from ${JSON.stringify(`${annotation.packageName}/react`)}`
  )
  const modules = extensions.map(
    ({ annotation }, index) =>
      `  ${JSON.stringify(annotation.name)}: annotation${index},`
  )

  return [
    header,
    "",
    ...imports,
    "",
    "export const annotationModules = {",
    ...modules,
    "} as const",
    "",
  ].join("\n")
}

async function writeIfChanged(path: string, content: string) {
  const current = await readFile(path, "utf8").catch(
    (error: NodeJS.ErrnoException) => {
      if (error.code === "ENOENT") return undefined
      throw error
    }
  )

  if (current !== content) await writeFile(path, content, "utf8")
}

export async function generateAnnotationConfigs(
  extensions: readonly AnnotationExtension[]
) {
  assertValidExtensions(extensions)
  const sourceDirectory = resolve(process.cwd(), "packages/annotations/src")

  await Promise.all([
    writeIfChanged(
      resolve(sourceDirectory, "annotations.config.ts"),
      generateBaseConfig(extensions)
    ),
    writeIfChanged(
      resolve(sourceDirectory, "react/annotations.config.ts"),
      generateReactConfig(extensions)
    ),
  ])
}
